type Row = { id: string; amount: number };
export function stableRows(rows: Row[]) {
  return [...rows].sort((a, b) => a.amount - b.amount || a.id.localeCompare(b.id));
}
export function visibleSelection(rows: Row[], selected: Set<string>) {
  return rows.filter(row => selected.has(row.id));
}

export function chartPoint(value: number | null) {
  if (value === null) return { value: null, label: '데이터 없음' };
  if (!Number.isFinite(value)) throw new Error('유효하지 않은 지표');
  return { value, label: new Intl.NumberFormat('ko-KR').format(value) };
}
// 결측 값을 0으로 바꾸지 않고 차트에서도 끊어진 구간으로 표현합니다.

type DrillFilter = { from: string; to: string; group: string };
export function drillLink(filter: DrillFilter) {
  const params = new URLSearchParams({
    from: filter.from, to: filter.to, group: filter.group
  });
  return '/records?' + params.toString();
}
// tenantId와 권한은 URL 입력값이 아니라 서버 세션에서 결정합니다.

export function validateQuantityRows(rows: string[][]) {
  return rows.map((cells, index) => {
    const quantity = cells[1]?.trim();
    return { row: index + 1, valid: /^\d+$/.test(quantity || '')
      && Number.isSafeInteger(Number(quantity)), cells };
  });
}
// rows는 따옴표·줄바꿈을 처리하는 CSV 파서의 결과입니다.

export function quoteCsvText(value: string) {
  const protectedValue = /^[\s]*[=+@-]/.test(value) ? "'" + value : value;
  return '"' + protectedValue.replaceAll('"', '""') + '"';
}
// 문자열 셀용 기본 완화 예시입니다. 대상 앱에서 저장·재열기까지 검증하고
// 민감한 내보내기는 XLSX의 명시적인 문자열 셀도 검토합니다.

export function visibleRange(scrollTop: number, viewport: number, rowHeight: number, count: number) {
  if (rowHeight <= 0 || count < 0) throw new Error('범위 설정 오류');
  const start = Math.max(0, Math.min(count, Math.floor(scrollTop / rowHeight) - 3));
  const end = Math.min(count, Math.ceil((scrollTop + viewport) / rowHeight) + 3);
  return { start, end, offset: start * rowHeight };
}
